// Model a secret moving through pipeline stages.
// A stage is a 'leak' if it writes the secret into a persistent,
// replayable artifact: an image layer (cached, in registry) or git.
const SECRET = 'sk-live-XYZ';

// Each stage declares the sink it writes the secret to, or null.
// SINK PERSISTENCE: image-layer=persistent, git=persistent,
// tmpfs-file=ephemeral, none=ephemeral.
const persistent = { 'image-layer': true, 'git': true, 'tmpfs-file': false, 'none': false };

function run(pipeline) {
  for (const stage of pipeline) {
    const sink = stage.writesTo;
    if (sink && persistent[sink]) {
      return 'LEAK at ' + stage.name + ' -> ' + sink;
    }
  }
  return 'SAFE: secret never hit a persistent artifact';
}

// CURRENT pipeline: bakes the secret into the image at build time.
const pipeline = [
  { name: 'build',   writesTo: 'image-layer' },  // ENV API_KEY=... / COPY .env .
  { name: 'deploy',  writesTo: 'none' },
  { name: 'runtime', writesTo: 'none' },
];

console.log(run(pipeline));
